// ---------------------------------------------------------------------------
//  Suchfenster festlegen
// ---------------------------------------------------------------------------
//  Der Agent liefert, was der Anrufer gesagt hat — oft nichts Genaues.
//  Hier wird daraus ein konkreter Zeitraum, den Google und die Datenbank
//  beide verstehen.

const k = $input.first().json.headers ?? {};
const b = $input.first().json.body ?? {};

const dauer = Math.min(Math.max(Number(b.dauer_minuten) || 30, 15), 120);

// Ab wann gesucht wird. Ein Vorlauf verhindert Vorschläge, die schon
// vorbei sind, bis der Anrufer aufgelegt hat.
const VORLAUF_STUNDEN = 3;
let ab = new Date(Date.now() + VORLAUF_STUNDEN * 3600e3);

if (b.ab_datum && /^\d{4}-\d{2}-\d{2}$/.test(b.ab_datum)) {
  const gewuenscht = new Date(`${b.ab_datum}T00:00:00+02:00`);
  if (!Number.isNaN(gewuenscht.getTime()) && gewuenscht > ab) ab = gewuenscht;
}

// Zwei Wochen sind genug. Wer weiter im Voraus plant, schreibt eine Mail.
const bis = new Date(ab.getTime() + 14 * 86400e3);

return [{
  json: {
    token: k['x-voice-token'] ?? '',
    ab: ab.toISOString(),
    bis: bis.toISOString(),
    dauer,
    tageszeit: ['vormittags', 'nachmittags'].includes(b.tageszeit) ? b.tageszeit : 'egal',
    conversation_id: b.conversation_id ?? null,
  },
}];

// ---------------------------------------------------------------------------
//  Freie Fenster ausrechnen
// ---------------------------------------------------------------------------
//  Google liefert nur, wann Damjan BELEGT ist. Wann er frei ist, ist das
//  Komplement — und zwar nicht gegen den ganzen Tag, sondern gegen seine
//  Sprechzeiten. "Frei" und "buchbar" sind zwei verschiedene Dinge:
//  Sonntag um drei Uhr nachts ist frei, aber niemand will da telefonieren.

const suche  = $('Suchfenster').first().json;
const regeln = $('Sprechzeiten und Sperren').first().json;
const google = $('Google: belegte Zeiten').first().json;

const ZONE = 'Europe/Berlin';
const dauerMs = suche.dauer * 60e3;

// --- Belegte Blöcke einsammeln ---------------------------------------------

const belegt = [];
let googleOk = false;

// Bei onError: continueRegularOutput liefert der Node statt einer
// Antwort ein { error: … }. Beides muss hier abgefangen werden.
if (google?.error) {
  console.warn(`Google-Node fehlgeschlagen: ${google.error.message ?? google.error}`);
} else if (google?.statusCode >= 200 && google?.statusCode < 300) {
  const kalender = google.body?.calendars ?? {};
  for (const [id, eintrag] of Object.entries(kalender)) {
    if (eintrag.errors?.length) {
      // Häufigster Fall: der Kalender wurde nie mit dem Dienstkonto geteilt.
      // Google meldet das NICHT als HTTP-Fehler, sondern still hier drin.
      console.warn(`Kalender ${id}: ${JSON.stringify(eintrag.errors)}`);
      continue;
    }
    googleOk = true;
    for (const b of eintrag.busy ?? []) {
      belegt.push([new Date(b.start).getTime(), new Date(b.end).getTime()]);
    }
  }
} else {
  console.warn(`Google freeBusy fehlgeschlagen: HTTP ${google?.statusCode}`);
}

// Ohne verwertbare Kalenderauskunft darf hier NICHTS vorgeschlagen werden.
// Ein Termin mitten in einem bestehenden Meeting ist schlimmer als die
// ehrliche Auskunft, dass es gerade nicht geht.
if (!googleOk) {
  return [{ json: {
    ok: false,
    vorschlaege: [],
    ansage: 'Ich komme gerade nicht an den Kalender. Ich notiere Ihren Terminwunsch, und Damjan meldet sich dazu.',
  } }];
}

for (const s of regeln.sperrzeiten ?? []) {
  belegt.push([new Date(s.starts_at).getTime(), new Date(s.ends_at).getTime()]);
}
for (const v of regeln.schon_vergeben ?? []) {
  belegt.push([new Date(v.starts_at).getTime(), new Date(v.ends_at).getTime()]);
}

belegt.sort((a, b) => a[0] - b[0]);

const kollidiert = (start, ende) =>
  belegt.some(([bs, be]) => start < be && ende > bs);

// --- Sprechzeiten je Tag durchgehen ----------------------------------------

// Wanduhrzeit in Berlin -> echter Zeitpunkt. Der Versatz zu UTC ist nicht
// konstant (Sommerzeit), also wird er für den jeweiligen Tag bestimmt.
function berlin(jahr, monat, tag, stunde, minute) {
  const roh = Date.UTC(jahr, monat - 1, tag, stunde, minute);
  const probe = new Date(roh);
  const versatz = (new Date(probe.toLocaleString('en-US', { timeZone: ZONE })) -
                   new Date(probe.toLocaleString('en-US', { timeZone: 'UTC' })));
  return new Date(roh - versatz);
}

const teile = (d) => {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: ZONE, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
  }).formatToParts(d).filter((x) => x.type !== 'literal').map((x) => [x.type, x.value]));
  return { jahr: +p.year, monat: +p.month, tag: +p.day };
};

const ab  = new Date(suche.ab);
const bis = new Date(suche.bis);
const nachWochentag = new Map();
for (const r of regeln.sprechzeiten ?? []) {
  if (!nachWochentag.has(r.weekday)) nachWochentag.set(r.weekday, []);
  nachWochentag.get(r.weekday).push(r);
}

const frei = [];

for (let tagVersatz = 0; tagVersatz < 21 && frei.length < 12; tagVersatz++) {
  const tagDatum = new Date(ab.getTime() + tagVersatz * 86400e3);
  if (tagDatum > bis) break;

  const { jahr, monat, tag } = teile(tagDatum);
  const wochentag = berlin(jahr, monat, tag, 12, 0).getDay();

  for (const regel of nachWochentag.get(wochentag) ?? []) {
    if (suche.tageszeit === 'vormittags' && parseInt(regel.start_time, 10) >= 12) continue;
    if (suche.tageszeit === 'nachmittags' && parseInt(regel.start_time, 10) < 12) continue;

    const [vonH, vonM] = regel.start_time.split(':').map(Number);
    const [bisH, bisM] = regel.end_time.split(':').map(Number);

    const fensterStart = berlin(jahr, monat, tag, vonH, vonM).getTime();
    const fensterEnde  = berlin(jahr, monat, tag, bisH, bisM).getTime();
    const raster = (regel.slot_minutes || 30) * 60e3;

    for (let t = fensterStart; t + dauerMs <= fensterEnde; t += raster) {
      if (t < ab.getTime()) continue;
      if (kollidiert(t, t + dauerMs)) continue;
      frei.push(new Date(t));
      // Höchstens zwei Vorschläge pro Tag — sonst klingt es nach
      // "der hat ja nie was zu tun".
      if (frei.filter((f) => teile(f).tag === tag).length >= 2) break;
    }
  }
}

if (!frei.length) {
  return [{ json: {
    ok: true, vorschlaege: [], ansage:
      'In den nächsten zwei Wochen ist leider nichts frei. Ich nehme Ihren Wunsch auf, und Damjan meldet sich mit einem Vorschlag.',
  } }];
}

// --- Fertige Sätze ----------------------------------------------------------

const auswahl = frei.slice(0, 3);
const lang = (d) => new Intl.DateTimeFormat('de-DE', {
  timeZone: ZONE, weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
}).format(d);
const kurz = (d) => {
  const s = new Intl.DateTimeFormat('de-DE', {
    timeZone: ZONE, weekday: 'long', hour: 'numeric', minute: '2-digit',
  }).format(d);
  return s.replace(', ', ' um ').replace(':00', '') + ' Uhr';
};

return [{ json: {
  ok: true,
  dauer_minuten: suche.dauer,
  vorschlaege: auswahl.map((d) => ({ start: d.toISOString(), lesbar: lang(d) })),
  // Zwei Optionen am Telefon. Drei überfordern, eine wirkt wie ein Ultimatum.
  ansage: auswahl.slice(0, 2).map(kurz).join(' oder ') +
    (auswahl.length > 2 ? ` — sonst hätte ich auch noch ${kurz(auswahl[2])}` : ''),
} }];
